import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq           INTEGER PRIMARY KEY AUTOINCREMENT,
  id            TEXT NOT NULL UNIQUE,
  status        TEXT NOT NULL,
  input         TEXT NOT NULL,
  steps         INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts      INTEGER NOT NULL DEFAULT 0,
  progress      INTEGER NOT NULL DEFAULT 0,
  output        TEXT NULL,
  error         TEXT NULL,
  idem_key      TEXT NULL UNIQUE,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  run_at        INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, run_at, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id      INTEGER PRIMARY KEY CHECK (id = 1),
  beat_at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, and ensures the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/** A row of the `jobs` table, as selected with `SELECT *`. */
export interface JobRow {
  seq: number;
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress: number;
  output: string | null;
  error: string | null;
  idem_key: string | null;
  created_at: string;
  updated_at: string;
  run_at: number;
}

/** The public JSON shape of a job. */
export function toJson(r: JobRow) {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress, total: r.steps },
    result: r.status === 'completed' ? { output: r.output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

export function nowIso(): string {
  return new Date().toISOString();
}

/** Runs `fn` inside a write transaction that starts immediately, so read-then-write sequences are atomic across processes. */
export function tx<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // The transaction may already be closed; the original error is the one worth reporting.
    }
    throw e;
  }
  return result;
}

