/** Pure validation for `POST /api/jobs`. Collects every problem so the client can show them all. */

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type SubmissionResult = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

export interface SubmissionRequest {
  body: string;
  contentType: string | undefined;
  idempotencyKey: string | undefined;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isIntInRange(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

export function validateSubmission(req: SubmissionRequest): SubmissionResult {
  const fields: FieldError[] = [];

  const mediaType = (req.contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  }

  if (req.idempotencyKey !== undefined && !IDEMPOTENCY_KEY_RE.test(req.idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(req.body);
  } catch {
    fields.push({ field: 'body', message: 'Body must be valid JSON' });
    return { ok: false, fields };
  }
  if (!isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object' });
    return { ok: false, fields };
  }

  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field' });
  }

  const { input, steps, failAttempts } = parsed;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Required string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace' });
  }

  let stepsValue = 5;
  if (steps !== undefined) {
    if (isIntInRange(steps, 1, 20)) stepsValue = steps;
    else fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20' });
  }

  let failValue = 0;
  if (failAttempts !== undefined) {
    if (isIntInRange(failAttempts, 0, 5)) failValue = failAttempts;
    else fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5' });
  }

  if (fields.length > 0 || typeof input !== 'string') return { ok: false, fields };
  return { ok: true, value: { input, steps: stepsValue, failAttempts: failValue } };
}

export { IDEMPOTENCY_KEY_RE };

