import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJson, tx, nowIso, type JobRow } from './db.ts';
import { validateSubmission } from './validate.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const HEARTBEAT_FRESH_MS = 3000;
const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string): void {
  sendJson(res, status, { error: { code, message } });
}

function sendInvalid(res: ServerResponse, fields: { field: string; message: string }[]): void {
  sendJson(res, 400, { error: { code: 'invalid_request', message: 'The request is invalid.', fields } });
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function getJobRow(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

function workerIsUp(): boolean {
  const hb = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  return hb !== undefined && Date.now() - Number(hb.beat_at) < HEARTBEAT_FRESH_MS;
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const keyHeader = req.headers['idempotency-key'];
  const idempotencyKey = typeof keyHeader === 'string' ? keyHeader : undefined;

  const result = validateSubmission({
    body,
    contentType: req.headers['content-type'],
    idempotencyKey,
  });
  if (!result.ok) return sendInvalid(res, result.fields);
  const payload = result.value;

  const outcome = tx(db, () => {
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idem_key = ?').get(idempotencyKey) as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === payload.input &&
          existing.steps === payload.steps &&
          existing.fail_attempts === payload.failAttempts;
        return same ? { status: 200 as const, row: existing } : { status: 409 as const };
      }
    }
    const id = randomUUID();
    const ts = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, idem_key, created_at, updated_at, run_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, idempotencyKey ?? null, ts, ts, Date.now());
    return { status: 201 as const, row: getJobRow(id)! };
  });

  if (outcome.status === 409) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  sendJson(res, outcome.status, toJson(outcome.row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  let allowed: string[];
  if (pathname === '/') allowed = ['GET'];
  else if (pathname === '/health') allowed = ['GET'];
  else if (pathname === '/api/jobs') allowed = ['GET', 'POST'];
  else if (JOB_PATH.test(pathname)) allowed = ['GET'];
  else return sendError(res, 404, 'not_found', 'No such route.');

  if (!allowed.includes(method)) {
    res.setHeader('Allow', allowed.join(', '));
    return sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return void res.end(uiHtml);
  }

  if (pathname === '/health') {
    return sendJson(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
  }

  if (pathname === '/api/jobs') {
    if (method === 'POST') return handleCreate(req, res);
    const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
    return sendJson(res, 200, { jobs: rows.map(toJson) });
  }

  const match = JOB_PATH.exec(pathname)!;
  let id: string;
  try {
    id = decodeURIComponent(match[1]!);
  } catch {
    return sendError(res, 404, 'not_found', 'No such job.');
  }
  const row = getJobRow(id);
  if (!row) return sendError(res, 404, 'not_found', 'No such job.');
  return sendJson(res, 200, toJson(row));
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
