const HEARTBEAT_MS = 500;
const IDLE_POLL_MS = 200;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

function beat(): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
  ).run(Date.now());
}

/** Returns a claimed job to the queue without counting the interrupted attempt. */
function releaseClaim(id: string): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_at = ?, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(Date.now(), nowIso(), id);
  });
}

function requeue(id: string, runAt: number): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'queued', progress = 0, run_at = ?, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(runAt, nowIso(), id);
  });
}

function fail(id: string): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'failed', error = 'transient failure', output = NULL, progress = 0, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(nowIso(), id);
  });
}

function complete(job: JobRow): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'completed', output = ?, progress = ?, error = NULL, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(job.input.toUpperCase(), job.steps, nowIso(), job.id);
  });
}

/** Claims the oldest runnable queued job, marking it running and counting the attempt. */
function claim(): JobRow | undefined {
  return tx(db, () => {
    const next = db
      .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_at <= ? ORDER BY seq ASC LIMIT 1`)
      .get(Date.now()) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ? WHERE id = ?`,
    ).run(nowIso(), next.id);
    return db.prepare('SELECT * FROM jobs WHERE id = ?').get(next.id) as JobRow;
  });
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure, before any progress.
    if (attempt >= MAX_ATTEMPTS) fail(job.id);
    else requeue(job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) {
      releaseClaim(job.id);
      return;
    }
    tx(db, () => {
      db.prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(
        i,
        nowIso(),
        job.id,
      );
    });
  }
  complete(job);
}

async function workLoop(): Promise<void> {
  while (!stopping) {
    let job: JobRow | undefined;
    try {
      job = claim();
    } catch (err) {
      console.error('claim failed:', err);
    }
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    try {
      await runAttempt(job);
    } catch (err) {
      console.error(`attempt for job ${job.id} failed:`, err);
      try {
        releaseClaim(job.id);
      } catch (releaseErr) {
        console.error('could not release job:', releaseErr);
      }
    }
  }
}

// Startup: requeue anything a previous worker left running, then announce ourselves.
releaseRecovered();
beat();
const heartbeat = setInterval(() => {
  try {
    beat();
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}, HEARTBEAT_MS);

function releaseRecovered(): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_at = ?, updated_at = ?
       WHERE status = 'running'`,
    ).run(Date.now(), nowIso());
  });
}

function onSignal(): void {
  stopping = true;
}
process.on('SIGTERM', onSignal);
process.on('SIGINT', onSignal);

console.log('worker started');
await workLoop();

clearInterval(heartbeat);
db.close();
process.exit(0);

