/** Pure validation for `POST /api/jobs`. Collects every problem so the client can show them all. */

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type SubmissionResult = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

export interface SubmissionRequest {
  body: string;
  contentType: string | undefined;
  idempotencyKey: string | undefined;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isIntInRange(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

export function validateSubmission(req: SubmissionRequest): SubmissionResult {
  const fields: FieldError[] = [];

  const mediaType = (req.contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  }

  if (req.idempotencyKey !== undefined && !IDEMPOTENCY_KEY_RE.test(req.idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(req.body);
  } catch {
    fields.push({ field: 'body', message: 'Body must be valid JSON' });
    return { ok: false, fields };
  }
  if (!isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object' });
    return { ok: false, fields };
  }

  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field' });
  }

  const { input, steps, failAttempts } = parsed;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Required string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace' });
  }

  let stepsValue = 5;
  if (steps !== undefined) {
    if (isIntInRange(steps, 1, 20)) stepsValue = steps;
    else fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20' });
  }

  let failValue = 0;
  if (failAttempts !== undefined) {
    if (isIntInRange(failAttempts, 0, 5)) failValue = failAttempts;
    else fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5' });
  }

  if (fields.length > 0 || typeof input !== 'string') return { ok: false, fields };
  return { ok: true, value: { input, steps: stepsValue, failAttempts: failValue } };
}

export { IDEMPOTENCY_KEY_RE };

import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, tx, nowIso, type JobRow } from './db.ts';

const HEARTBEAT_MS = 500;
const IDLE_POLL_MS = 200;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

function beat(): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
  ).run(Date.now());
}

/** Returns a claimed job to the queue without counting the interrupted attempt. */
function releaseClaim(id: string): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_at = ?, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(Date.now(), nowIso(), id);
  });
}

function requeue(id: string, runAt: number): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'queued', progress = 0, run_at = ?, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(runAt, nowIso(), id);
  });
}

function fail(id: string): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'failed', error = 'transient failure', output = NULL, progress = 0, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(nowIso(), id);
  });
}

function complete(job: JobRow): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'completed', output = ?, progress = ?, error = NULL, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(job.input.toUpperCase(), job.steps, nowIso(), job.id);
  });
}

/** Claims the oldest runnable queued job, marking it running and counting the attempt. */
function claim(): JobRow | undefined {
  return tx(db, () => {
    const next = db
      .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_at <= ? ORDER BY seq ASC LIMIT 1`)
      .get(Date.now()) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ? WHERE id = ?`,
    ).run(nowIso(), next.id);
    return db.prepare('SELECT * FROM jobs WHERE id = ?').get(next.id) as JobRow;
  });
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure, before any progress.
    if (attempt >= MAX_ATTEMPTS) fail(job.id);
    else requeue(job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) {
      releaseClaim(job.id);
      return;
    }
    tx(db, () => {
      db.prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(
        i,
        nowIso(),
        job.id,
      );
    });
  }
  complete(job);
}

async function workLoop(): Promise<void> {
  while (!stopping) {
    let job: JobRow | undefined;
    try {
      job = claim();
    } catch (err) {
      console.error('claim failed:', err);
    }
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    try {
      await runAttempt(job);
    } catch (err) {
      console.error(`attempt for job ${job.id} failed:`, err);
      try {
        releaseClaim(job.id);
      } catch (releaseErr) {
        console.error('could not release job:', releaseErr);
      }
    }
  }
}

/** At startup, requeues jobs a previous worker left running (it died mid-attempt; the attempt is redone). */
function recoverInterrupted(): void {
  tx(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_at = ?, updated_at = ?
       WHERE status = 'running'`,
    ).run(Date.now(), nowIso());
  });
}

// Startup: requeue anything a previous worker left running, then announce ourselves.
recoverInterrupted();
beat();
const heartbeat = setInterval(() => {
  try {
    beat();
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}, HEARTBEAT_MS);

function onSignal(): void {
  stopping = true;
}
process.on('SIGTERM', onSignal);
process.on('SIGINT', onSignal);

console.log('worker started');
await workLoop();

clearInterval(heartbeat);
db.close();
process.exit(0);

